import networkx as nx
import itertools

def find_graph():
    for edges in itertools.combinations(itertools.combinations(range(11), 2), 7):
        G = nx.Graph()
        G.add_nodes_from(range(11))
        G.add_edges_from(edges)
        G.add_edges_from([(3,7), (2,9), (0,9)])  # Add fixed edges
        if all(3 <= G.degree(node) <= 5 for node in G.nodes()) and 7 <= G.number_of_edges() <= 19:
            coloring = nx.greedy_color(G)
            if max(coloring.values()) + 1 <= 4 and max(coloring.values()) + 1 >= 3:
                return list(G.edges)
    return "UNSATISFIABLE"

print(find_graph())
